def aaa(s):
 s=replacements(s,[('data-diagram="aaaLifecycle"','data-diagram="aaaLifecycle" data-relationship="illustrative-access"'),('Identification to Authentication to Authorization to Accounting','Illustrative identity claim, proof and permission, with ongoing accounting'),('>STEP 04<','>ONGOING<'),('<span class="reading-mob-tier-num">04</span>','<span class="reading-mob-tier-num">LOG</span>'),('<!-- Step 4: Accounting -->\n      <g>','<!-- Accounting throughout the example -->\n      <g data-concept="accounting" data-scope="ongoing">')])
 s=re.sub(r'      <g>\s*<line x1="565"[\s\S]*?</g>\n','',s,count=1)
 old='<p class="reading-semantic-note">Accounting (Audit Logs) บันทึกเหตุการณ์อย่างต่อเนื่องตลอดการใช้งานเพื่อสนับสนุน Accountability และการไม่สามารถปฏิเสธความรับผิดชอบได้ (Non-repudiation)</p>'
 s=s.replace(old,'<p class="reading-semantic-note">Accounting records relevant events throughout the access example, including failed authentication attempts. Logs support accountability when protected and reliably linked to identity; non-repudiation also depends on suitable evidence and controls. / Accounting บันทึกเหตุการณ์ที่เกี่ยวข้องตลอดตัวอย่าง รวมถึงการพิสูจน์ตัวตนที่ไม่สำเร็จ Log ที่ได้รับการปกป้องช่วยสนับสนุน Accountability ส่วน Non-repudiation ต้องพิจารณาหลักฐานและมาตรการประกอบ</p>')
 return s
